import sys, os, pickle, stat

W = 10
PAD = 4096

def work(chunk):
    parts = chunk.replace(b"\n", b",").split(b",")
    if parts and parts[-1] == b"":
        parts.pop()
    sums = {}
    g = sums.get
    for c, v in zip(parts[1::3], map(float, parts[2::3])):
        sums[c] = g(c, 0.0) + v
    return sums

def main():
    fd = 0
    try:
        st = os.fstat(fd)
        isreg = stat.S_ISREG(st.st_mode) and st.st_size > 0
    except OSError:
        isreg = False
    if isreg:
        n = st.st_size
        data = None
        head = os.pread(fd, 4096, 0)
    else:
        data = sys.stdin.buffer.read()
        n = len(data)
        head = data[:4096]
    start = head.find(b"\n") + 1
    approx = [start + (n - start) * i // W for i in range(W + 1)]
    pipes = []
    for i in range(W):
        a, b = approx[i], approx[i + 1]
        if a >= n:
            continue
        r, w = os.pipe()
        pid = os.fork()
        if pid == 0:
            os.close(r)
            if data is None:
                buf = os.pread(fd, b - a + PAD, a)
            else:
                buf = data[a:b + PAD]
            s = 0
            if i > 0:
                p = buf.find(b"\n")
                s = len(buf) if p < 0 else p + 1
            if i + 1 < W:
                p = buf.find(b"\n", b - a)
                e = len(buf) if p < 0 else p + 1
            else:
                e = len(buf)
            res = pickle.dumps(work(buf[s:e]) if s < e else {}, protocol=pickle.HIGHEST_PROTOCOL)
            while res:
                k = os.write(w, res)
                res = res[k:]
            os._exit(0)
        os.close(w)
        pipes.append((pid, r))
    total = {}
    for pid, r in pipes:
        chunks = []
        while True:
            c = os.read(r, 65536)
            if not c:
                break
            chunks.append(c)
        os.close(r)
        os.waitpid(pid, 0)
        g = total.get
        for k, v in pickle.loads(b"".join(chunks)).items():
            total[k] = g(k, 0.0) + v
    sys.stdout.write("".join("%s,%.2f\n" % (k.decode(), v) for k, v in sorted(total.items())))

main()

